def _fill_usernames(apps, schema_editor):
    import random
    import re

    Student = apps.get_model("frontend", "Student")

    def norm(text):
        mapping = {
            "o'": "o", "g'": "g",
            "O'": "O", "G'": "G",
            "ь": "", "ъ": "",
        }
        out = text
        for k, v in mapping.items():
            out = out.replace(k, v)
        return re.sub(r"[^a-zA-Z0-9_]+", "", out).strip("_").lower()

    existing = set(Student.objects.exclude(username__isnull=True).values_list("username", flat=True))

    def pick(base, pk):
        cand = base or f"user{pk}"
        for i in range(0, 100):
            c = cand if i == 0 else f"{cand}_{i}"
            if c not in existing:
                existing.add(c)
                return c
        c = f"{cand}_{pk}_{random.randint(1000, 9999)}"
        existing.add(c)
        return c

    for st in Student.objects.all().iterator():
        if st.username:
            continue
        st.username = pick(norm(f"{st.first_name}{st.last_name}"), st.pk)
        st.save(update_fields=["username"])


